/// Connection settings read from a small `key = value` file.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Config {
    pub host: String,
    pub port: u16,
    pub retries: u32,
}

/// Parses `key = value` lines. Blank lines and lines starting with `#` are ignored.
pub fn parse_config(text: &str) -> Config {
    let mut host = None;
    let mut port = None;
    let mut retries = 3;
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (key, value) = line.split_once('=').expect("missing '='");
        let key = key.trim();
        let value = value.trim();
        match key {
            "host" => host = Some(value.to_string()),
            "port" => port = Some(value.parse().unwrap()),
            "retries" => retries = value.parse().unwrap(),
            other => panic!("unknown key {other}"),
        }
    }
    Config {
        host: host.expect("host is required"),
        port: port.expect("port is required"),
        retries,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_a_complete_file() {
        let config = parse_config("# service\nhost = example.org\nport = 8080\n\nretries = 5\n");
        assert_eq!(
            config,
            Config {
                host: "example.org".to_string(),
                port: 8080,
                retries: 5,
            }
        );
    }
}

