use fixture::{Config, ConfigError, parse_config};

fn assert_error_type<E: std::error::Error + Clone + Eq + 'static>() {}

fn key(line: usize, key: &str) -> (usize, String) {
    (line, key.to_string())
}

#[test]
fn parses_valid_files() {
    let config = parse_config("# service\n  host = example.org \nport=8080\n\nretries = 5\n").unwrap();
    assert_eq!(
        config,
        Config { host: "example.org".to_string(), port: 8080, retries: 5 }
    );
    let defaults = parse_config("port = 1\r\n   # note\r\nhost = a=b\r\n").unwrap();
    assert_eq!(defaults, Config { host: "a=b".to_string(), port: 1, retries: 3 });
    assert_eq!(parse_config("host=h\nport=65535\nretries=0").unwrap().port, 65535);
}

#[test]
fn syntax_errors() {
    assert_eq!(parse_config("host = a\nport 80\n"), Err(ConfigError::Syntax { line: 2 }));
    assert_eq!(parse_config("\n\n  just text  "), Err(ConfigError::Syntax { line: 3 }));
}

#[test]
fn unknown_and_duplicate_keys() {
    let (line, name) = key(2, "timeout");
    assert_eq!(
        parse_config("host = a\ntimeout = 5\nport = x"),
        Err(ConfigError::UnknownKey { line, key: name })
    );
    assert_eq!(
        parse_config("= 5"),
        Err(ConfigError::UnknownKey { line: 1, key: String::new() })
    );
    assert_eq!(
        parse_config("Host = a"),
        Err(ConfigError::UnknownKey { line: 1, key: "Host".to_string() })
    );
    let (line, name) = key(3, "host");
    assert_eq!(
        parse_config("host = a\n# x\nhost = b\nport = 1"),
        Err(ConfigError::DuplicateKey { line, key: name })
    );
    assert_eq!(
        parse_config("retries = 1\nretries = 1\nhost = a\nport = 1"),
        Err(ConfigError::DuplicateKey { line: 2, key: "retries".to_string() })
    );
}

#[test]
fn invalid_values() {
    let invalid = |line: usize, key: &str, value: &str| ConfigError::InvalidValue {
        line,
        key: key.to_string(),
        value: value.to_string(),
    };
    assert_eq!(parse_config("host = a\nport = 0"), Err(invalid(2, "port", "0")));
    assert_eq!(parse_config("host = a\nport = 65536"), Err(invalid(2, "port", "65536")));
    assert_eq!(parse_config("port = -1"), Err(invalid(1, "port", "-1")));
    assert_eq!(parse_config("port = eighty"), Err(invalid(1, "port", "eighty")));
    assert_eq!(parse_config("port = "), Err(invalid(1, "port", "")));
    assert_eq!(parse_config("host =   "), Err(invalid(1, "host", "")));
    assert_eq!(
        parse_config("host = a\nport = 1\nretries = 4294967296"),
        Err(invalid(3, "retries", "4294967296"))
    );
    assert_eq!(parse_config("retries = many\nbad"), Err(invalid(1, "retries", "many")));
}

#[test]
fn missing_keys() {
    assert_eq!(parse_config(""), Err(ConfigError::MissingKey("host".to_string())));
    assert_eq!(parse_config("port = 80"), Err(ConfigError::MissingKey("host".to_string())));
    assert_eq!(parse_config("host = a\n# port = 80"), Err(ConfigError::MissingKey("port".to_string())));
}

#[test]
fn never_panics_and_errors_display() {
    assert_error_type::<ConfigError>();
    for text in ["=", "==", "#", "\u{0}", "host", "port = \u{1F600}", "host = \u{e9}\nport = 99999999999999999999"] {
        if let Err(error) = parse_config(text) {
            assert!(!error.to_string().is_empty());
            let boxed: Box<dyn std::error::Error> = Box::new(error);
            assert!(!boxed.to_string().is_empty());
        }
    }
}
